insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-23','opgelost','Calculatie','Calculatie importeren lukt weer bij een oude koppeling',
   'Hing er aan een dossier nog een calculatie die eerder was verwijderd, dan mislukte het importeren van een .c4y-bestand of opname met een foutmelding. EVA maakt in dat geval nu zelf een nieuwe calculatie aan, zodat de import gewoon wordt opgeslagen.');
